// Build dedup context from previous newsletters stored in Notion
const items = $input.all();
let dedupContext = '';
let lastNewsletterDate = '';

if (items.length > 0 && items[0].json.properties) {
  for (const item of items) {
    const props = item.json.properties || {};
    const date = props['Date']?.date?.start || props['Created']?.created_time?.split('T')[0] || 'Unknown';
    if (!lastNewsletterDate) lastNewsletterDate = date;
    const name = props['Name']?.title?.[0]?.plain_text || '';
    const tldr = props['TL;DR']?.rich_text?.[0]?.plain_text || '';
    const signals = props['Key Signals']?.rich_text?.[0]?.plain_text || '';
    dedupContext += `\n--- ${name} (${date}) ---\nTL;DR: ${tldr}\nSignals covered: ${signals}\n`;
  }
} else {
  dedupContext = 'No previous newsletters found. This is the first issue.';
}

const readableDate = $('Date & Time').first().json['Readable date'] || new Date().toLocaleDateString('en-GB');

return [{
  json: {
    previousContext: dedupContext,
    lastNewsletterDate: lastNewsletterDate,
    readableDate: readableDate
  }
}];

// Parse AI Agent output: extract subject, HTML, TL;DR, and key signals for Notion logging
const agentOutput = $input.first().json.output || $input.first().json.text || '';
const readableDate = $('Date & Time').first().json['Readable date'] || new Date().toLocaleDateString('en-GB');

// Extract TL;DR for Notion logging
let tldrExcerpt = '';
const tldrMatch = agentOutput.match(/TL;DR[\s\S]*?<ul[^>]*>([\s\S]*?)<\/ul>/i);
if (tldrMatch) {
  tldrExcerpt = tldrMatch[1]
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 2000);
}

// Extract key signals (bold headlines from the body)
let keySignals = '';
const headlineMatches = agentOutput.match(/<strong>([^<]+)<\/strong>/g);
if (headlineMatches) {
  keySignals = headlineMatches
    .map(h => h.replace(/<\/?strong>/g, ''))
    .filter(h => h !== 'TL;DR' && h.length > 5 && h.length < 200)
    .slice(0, 10)
    .join(', ')
    .substring(0, 2000);
}

const subject = `\u{1F984} Riterz Commercial Intelligence | ${readableDate}`;

return [{
  json: {
    subject: subject,
    htmlBody: agentOutput,
    tldrExcerpt: tldrExcerpt,
    keySignals: keySignals,
    date: new Date().toISOString().split('T')[0]
  }
}];
